private static String[] copyStrings(final String[] src) {
    // Check if the source array is null or empty
    if (src == null || src.length == 0) {
        return new String[0];
    }

    // Create a new array to hold the copied strings
    String[] dst = new String[src.length];

    // Iterate over the source array
    for (int i = 0; i < src.length; i++) {
        // Check if the current element is null
        if (src[i] == null) {
            dst[i] = null;
        } else {
            // Convert the string to lower case and store it in the destination array
            dst[i] = src[i].toLowerCase();
        }
    }

    // Return the new array with lower-case strings
    return dst;
}

