public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null || resultMap.isEmpty()) {
        throw new IllegalArgumentException("Invalid input: target graph and resultMap cannot be null or empty");
    }

    Set<V> vertices = new HashSet<>(resultMap.values());

    // Create two sets of vertices, A and B, to form a bipartite graph
    Set<V> setA = new HashSet<>(vertices.size() / 2);
    Set<V> setB = new HashSet<>(vertices.size() - setA.size());

    // Distribute vertices between setA and setB
    int index = 0;
    for (V vertex : vertices) {
        if (index % 2 == 0) {
            setA.add(vertex);
        } else {
            setB.add(vertex);
        }
        index++;
    }

    // Add edges between setA and setB
    for (V vertexA : setA) {
        for (V vertexB : setB) {
            if (!target.containsEdge(vertexA, vertexB)) {
