    List<Pair<List<Pair<Integer, Integer>>, E>> result = new ArrayList<>();

    if (graph == null || graph.getVertices().isEmpty() || graph.getEdges().isEmpty()) {
        return result; // Return empty list if the graph is null or has no vertices/edges
    }

    for (E edge : graph.getEdges()) {
        Set<Integer> vertices = graph.getEdgeVertices(edge);
        if (vertices == null || vertices.size() != 2) {
            continue; // Skip invalid edges
        }

        Integer vertex1 = vertices.iterator().next();
        vertices.remove(vertex1);
        Integer vertex2 = vertices.iterator().next();

        Set<Integer> neighborhood1 = graph.getNeighbors(vertex1);
        Set<Integer> neighborhood2 = graph.getNeighbors(vertex2);
        neighborhood1.retainAll(neighborhood2); // Intersection of neighborhoods

        List<Pair<Integer, Integer>> minimalSeparators = new ArrayList<>();
        for (Integer separator : neighborhood1) {
            if (separator != vertex1 && separator != vertex2) {
                minimalSeparators.add(new Pair<>(separator, separator));
            }
        }

        result.add(new Pair<>(minimalSeparators, edge));
    }

    return result;
}

