private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph or vertices are null
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices cannot be null");
    }

    // Get the set of edges in the induced subgraph
    Set<E> subgraphEdges = new HashSet<>();
    for (V u : vertices) {
        for (V v : vertices) {
            if (u != v && graph.containsEdge(u, v)) {
                subgraphEdges.add(graph.getEdge(u, v));
            }
        }
    }

    // Calculate the expected number of edges in a clique
    int n = vertices.size();
    int expectedEdges = n * (n - 1) / 2;

    // Check if the number of edges in the subgraph is equal to the expected number
    return subgraphEdges.size() == expectedEdges;
}

