    }

    // Ensure there are enough bytes remaining to decode
    if (i + 4 > bb.remaining()) {
        throw new IllegalArgumentException("Not enough bytes to decode at index: " + i);
    }

    // Read the first octet
    byte firstOctet = bb.get(i);

    // Determine the number of bytes to read based on the first octet
    int numBytes = 1;
    if ((firstOctet & 0x80) != 0) {
        if ((firstOctet & 0xE0) == 0xC0) {
            numBytes = 2;
        } else if ((firstOctet & 0xF0) == 0xE0) {
            numBytes = 3;
        } else if ((firstOctet & 0xF8) == 0xF0) {
            numBytes = 4;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 start byte: " + firstOctet);
        }
    }

    // Ensure there are enough bytes remaining in the ByteBuffer
