    if (message == null) {
        message = "";
    }

    // Step 3: Retrieve the logger name from the event
    String loggerName = event.getLoggerName();
    if (loggerName == null) {
        loggerName = "Unknown logger";
    }

    // Step 4: Retrieve the time of event occurrence
    long timestamp = event.getTimeStamp();

    // Step 5: Format the message
    String formattedMessage = String.format(
        "%s - %s - %s",
        timestamp,
        loggerName,
        message
    );

    return formattedMessage;
}

