public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Both table and pane must not be null");
    }

    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Row index " + row + " is out of bounds for the table");
    }

    table.setRowSelectionInterval(row, row);
    JViewport viewport = pane.getViewport();
    if (viewport == null) {
        throw new IllegalStateException("Viewport not found in the scroll pane");
    }

    Rectangle cellRect = table.getCellRect(row, 0, true);
    if (cellRect != null) {
        viewport.setViewPosition(new Point(0, cellRect.y));
    }

    table.repaint();
    try {
        SwingUtilities.invokeLater(() -> table.repaint());
        Thread.sleep(100); // Delay of 100 milliseconds to ensure repaint
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
        // Handle or log the interruption if necessary
    }
}

