public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> sequenceRanges = new ArrayList<>();
    // Assuming there is a method getProfiles() that returns a list of profiles
    List<Profile> profiles = getProfiles();

    if (profiles == null || profiles.isEmpty()) {
        return sequenceRanges;
    }

    profiles.sort((p1, p2) -> Long.compare(p1.getStartTime(), p2.getStartTime()));

    for (int i = 0; i < profiles.size() - 1; i++) {
        Profile current = profiles.get(i);
        Profile next = profiles.get(i + 1);

        long currentEnd = current.getEndTime();
        long nextStart = next.getStartTime();

        if (currentEnd < nextStart) {
            sequenceRanges.add(new SequenceRange(currentEnd, nextStart));
        }
    }

    return sequenceRanges;
}

